CREATE TABLE agent_runs (id TEXT PRIMARY KEY,office_id TEXT NOT NULL,requester_id TEXT NOT NULL REFERENCES users(user_id),request_key TEXT NOT NULL,input TEXT NOT NULL,state TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,model_calls INTEGER NOT NULL DEFAULT 0,lease_token TEXT,lease_owner TEXT,lease_until INTEGER,reason TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(office_id,requester_id,request_key),FOREIGN KEY(requester_id,office_id) REFERENCES office_memberships(user_id,office_id));
CREATE UNIQUE INDEX agent_one_active_office ON agent_runs(office_id) WHERE state IN ('queued','working','waiting_for_person','waiting_for_approval','ready_for_review');
CREATE TABLE agent_requests(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES agent_runs(id),recipient_id TEXT NOT NULL REFERENCES users(user_id),question TEXT NOT NULL,reason TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'open',answer TEXT,allow_publication INTEGER NOT NULL DEFAULT 0,response_key TEXT,response_input TEXT,expires_at TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(run_id,recipient_id));
CREATE TABLE agent_artifacts(run_id TEXT NOT NULL REFERENCES agent_runs(id),revision INTEGER NOT NULL,content TEXT NOT NULL,evidence TEXT NOT NULL,partial INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL,PRIMARY KEY(run_id,revision));
CREATE TABLE agent_events(cursor INTEGER PRIMARY KEY AUTOINCREMENT,run_id TEXT NOT NULL REFERENCES agent_runs(id),type TEXT NOT NULL,data TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE agent_outbox(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES agent_runs(id),kind TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL,UNIQUE(run_id,kind,id));
CREATE TABLE agent_reviews(run_id TEXT NOT NULL REFERENCES agent_runs(id),request_key TEXT NOT NULL,input TEXT NOT NULL,artifact_revision INTEGER NOT NULL,decision TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(run_id,request_key));
